CREATE TABLE e2ee_prekeys (id UUID PRIMARY KEY, tenant_id VARCHAR NOT NULL, user_email VARCHAR NOT NULL, prekey_id VARCHAR NOT NULL, public_key TEXT NOT NULL, private_key_encrypted TEXT NOT NULL, used BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(tenant_id, user_email, prekey_id)); CREATE INDEX idx_e2ee_prekeys_user ON e2ee_prekeys(tenant_id, user_email, used);
